const D = { density: .5, scale: 1, energy: .62, speed: 1, hue: 205, x: .5, y: .5, glow: .55, style: 'quasi-octagon', act: 'sweep', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity != null ? K.intensity : .6);
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat; S.lastBeat = K.beat;

const SQ = Math.SQRT1_2, H = (1 + Math.SQRT2) / 2;
const BS = Math.ceil(1.5 * Math.max(width, height));
const dens = Math.min(1, Math.max(0, P.density));
let edgePx = BS * 0.085 * P.scale / (0.55 + dens * 1.4);
const minEdge = BS * 0.72 / 22;
if (edgePx < minEdge) edgePx = minEdge;
const genR = BS * 0.75;
const Rphys = genR / edgePx;

const key = [BS, edgePx.toFixed(2), st, P.seed].join('|');
if (S.key !== key) {
  S.key = key;
  const gx = (fr(1) - 0.5) * 0.5, gy = (fr(2) - 0.5) * 0.5;
  const N = Math.ceil(Rphys) + 3;
  const cc = BS * 0.5;
  const map = new Map(), verts = [];
  const accept = (a, b, c, d) => {
    const yx = a - SQ * b + SQ * d + gx;
    const yy = b * SQ - c + d * SQ + gy;
    if (Math.abs(yx) > H) return false;
    if (Math.abs(yy) > H) return false;
    if (Math.abs((yx + yy) * SQ) > H) return false;
    if (Math.abs((yy - yx) * SQ) > H) return false;
    return true;
  };
  for (let n1 = -N; n1 <= N; n1++) for (let n3 = -N; n3 <= N; n3++) {
    const c0 = SQ * (n1 - n3) - gx, c2 = SQ * (n1 + n3) + gy;
    for (let n0 = Math.floor(c0 - H); n0 <= Math.ceil(c0 + H); n0++)
      for (let n2 = Math.floor(c2 - H); n2 <= Math.ceil(c2 + H); n2++) {
        if (!accept(n0, n1, n2, n3)) continue;
        const px = (n0 + n1 * SQ - n3 * SQ) * edgePx;
        const py = (n1 * SQ + n2 + n3 * SQ) * edgePx;
        if (px * px + py * py > genR * genR) continue;
        const kk = n0 + ',' + n1 + ',' + n2 + ',' + n3;
        if (map.has(kk)) continue;
        const rec = { n: [n0, n1, n2, n3], x: cc + px, y: cc + py, r: Math.hypot(px, py) / genR };
        map.set(kk, rec); verts.push(rec);
      }
  }
  const pairs = [[0, 1], [0, 2], [0, 3], [1, 2], [1, 3], [2, 3]];
  const mk = (nn, inc) => (nn[0] + inc[0]) + ',' + (nn[1] + inc[1]) + ',' + (nn[2] + inc[2]) + ',' + (nn[3] + inc[3]);
  const tiles = [];
  for (const rec of verts) {
    const nn = rec.n;
    for (const pr of pairs) {
      const j = pr[0], k = pr[1];
      const ij = [0, 0, 0, 0]; ij[j] = 1;
      const ik = [0, 0, 0, 0]; ik[k] = 1;
      const ijk = [0, 0, 0, 0]; ijk[j] = 1; ijk[k] = 1;
      const rj = map.get(mk(nn, ij)), rk = map.get(mk(nn, ik)), rjk = map.get(mk(nn, ijk));
      if (!rj || !rk || !rjk) continue;
      tiles.push({ x0: rec.x, y0: rec.y, x1: rj.x, y1: rj.y, x2: rjk.x, y2: rjk.y, x3: rk.x, y3: rk.y,
        type: (Math.abs(j - k) === 2) ? 1 : 0, r: rec.r, jit: ((nn[0] * 7 + nn[1] * 13 + nn[2] * 17 + nn[3] * 23) * 0.61803) % 1 });
    }
  }

  // ---- bake tiling into buffer ----
  if (S.buf) S.buf.remove();
  const g = createGraphics(BS, BS); S.buf = g; S.BS = BS;
  g.colorMode(g.HSB, 360, 100, 100, 100);
  g.push();
  if (st === 'quasi-octagon') g.background((P.hue + 18) % 360, 42, 9);
  else if (st === 'stained-glass') g.background(0, 0, 4);
  else if (st === 'neon-lattice') g.background(232, 60, 5);
  else if (st === 'blueprint') g.background(220, 72, 13);
  else g.background(40, 12, 86);
  const jf = Math.max(0.6, edgePx);
  for (const t of tiles) {
    const jit = t.jit < 0 ? t.jit + 1 : t.jit;
    if (st === 'quasi-octagon') {
      if (t.type === 1) g.fill(P.hue, 66, 50 + jit * 16 + (1 - t.r) * 10);
      else g.fill((P.hue + 150) % 360, 58, 46 + jit * 16 + (1 - t.r) * 10);
      g.stroke((P.hue + 18) % 360, 55, 14); g.strokeWeight(Math.max(1, jf * 0.03));
    } else if (st === 'stained-glass') {
      const hh = (P.hue + t.r * 130 + t.type * 46 + jit * 22) % 360;
      g.fill(hh, 80, 40 + jit * 24 + (t.type ? 6 : 0));
      g.stroke(0, 0, 3); g.strokeWeight(Math.max(1.4, jf * 0.075));
    } else if (st === 'neon-lattice') {
      g.fill(232, 52, 7 + (1 - t.r) * 4);
      const hh = (P.hue + t.type * 150 + t.r * 70) % 360;
      g.stroke(hh, 82, 96); g.strokeWeight(Math.max(1, jf * 0.028));
    } else if (st === 'blueprint') {
      g.noFill();
      g.stroke(196, 68, 92); g.strokeWeight(Math.max(1, jf * 0.024));
    } else { // ink
      if (t.type === 1 && jit > 0.62) { g.fill(38, 16, 44, 42); } else g.noFill();
      g.stroke(34, 32, 22, 90); g.strokeWeight(Math.max(1, jf * 0.045 * (0.7 + jit * 0.7)));
    }
    g.beginShape();
    g.vertex(t.x0, t.y0); g.vertex(t.x1, t.y1); g.vertex(t.x2, t.y2); g.vertex(t.x3, t.y3);
    g.endShape(g.CLOSE);
  }

  // ---- Ammann bars (quasiperiodic straight-line grid, 4 directions) ----
  const bars = [];
  const shortS = edgePx * 0.9, longS = shortS * Math.SQRT2, al = Math.SQRT2 - 1;
  for (let m = 0; m < 4; m++) {
    const ang = m * Math.PI / 4, nx = Math.cos(ang), ny = Math.sin(ang), ph = fr(10 + m) * 3.3;
    let pos = (fr(20 + m) - 0.5) * edgePx, i = 0;
    while (pos < genR * 1.05) {
      bars.push({ nx, ny, t: pos, m });
      const sf = Math.floor((i + 1) * al + ph) - Math.floor(i * al + ph);
      pos += sf ? longS : shortS; i++;
    }
    pos = (fr(20 + m) - 0.5) * edgePx; i = 0;
    while (pos > -genR * 1.05) {
      const sf = Math.floor((i + 1) * al + ph) - Math.floor(i * al + ph);
      pos -= sf ? longS : shortS; i++;
      bars.push({ nx, ny, t: pos, m });
    }
  }
  // faint baked baseline of the bars so they read even outside the highlight
  if (st !== 'ink') {
    const L0 = genR * 1.2;
    const bc = st === 'blueprint' ? [196, 60, 60] : (st === 'neon-lattice' ? [(P.hue + 30) % 360, 40, 55] : [(P.hue + 40) % 360, 30, 55]);
    g.strokeWeight(1);
    for (const b of bars) {
      const mx = cc + b.nx * b.t, my = cc + b.ny * b.t, dx = -b.ny, dy = b.nx;
      g.stroke(bc[0], bc[1], bc[2], st === 'blueprint' ? 26 : 15);
      g.line(mx - dx * L0, my - dy * L0, mx + dx * L0, my + dy * L0);
    }
  }
  g.pop();
  S.bars = bars; S.genR = genR;
}

// ================= live frame =================
const rot = K.t * (0.006 + 0.02 * P.speed);
push();
translate(width * 0.5, height * 0.5);
rotate(rot);
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.buf, -S.BS * 0.5, -S.BS * 0.5);

// traveling luminous highlight along the Ammann bars
const range = S.genR;
const sweepPos = Math.sin(K.t * (0.03 + 0.10 * P.speed)) * range;
const sweepAng = K.t * (0.01 + 0.04 * P.speed);
const sdx = Math.cos(sweepAng), sdy = Math.sin(sweepAng);
const sigma = range * (0.10 + P.glow * 0.16 + intn * 0.05);
const peak = 0.4 + P.energy * 0.9 + intn * 0.3 + A.rms * 0.6;
const secDrift = (K.section || 0) * 15; // slow palette rotation across the 8 sections
const baseGlow = (st === 'blueprint' || st === 'ink') ? 0.14 : 0.20;
const L = range * 1.2;
blendMode(ADD);
for (const b of S.bars) {
  const mx = b.nx * b.t, my = b.ny * b.t;
  const proj = mx * sdx + my * sdy;
  const dd = proj - sweepPos;
  const band = Math.exp(-(dd * dd) / (2 * sigma * sigma));
  const bri = baseGlow + band * peak * 0.9;
  if (bri < 0.03) continue;
  const dx = -b.ny, dy = b.nx;
  const hh = (P.hue + b.m * 12 + 34 + secDrift) % 360;
  strokeWeight(1 + band * 2.6);
  stroke(hh, 26 + band * 24, 100, Math.min(58, bri * 55));
  line(mx - dx * L, my - dy * L, mx + dx * L, my + dy * L);
}
blendMode(BLEND);
pop();

// partial-frame beat bloom on the central octagonal sun (never full-frame flash)
const beatBloom = K.pulse * 0.5 + A.bass * 0.8;
if (beatBloom > 0.04) {
  push(); blendMode(ADD); noStroke();
  fill((P.hue + 40) % 360, 28, 100, beatBloom * 9);
  circle(width * 0.5, height * 0.5, u * 0.5 * (1 + beatBloom * 0.15));
  blendMode(BLEND); pop();
}
